/**
 * @file sim_display.c
 * @brief X11 窗口 + LVGL display/indev 绑定；headless 下只维护影子帧缓冲。
 *
 * 为什么不照搬 lv_port_linux：那个工程是 Kconfig/CMake 组件化的，源文件
 * 依赖它的 SDK 框架。这里只要"一块 RGB565 画布 + 鼠标键盘"，自己写
 * 200 行比拖一整套框架干净，而且窗口缩放、headless 截图都能自己控制。
 */

#define _POSIX_C_SOURCE 199309L

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#include <X11/Xlib.h>
#include <X11/Xutil.h>
#include <X11/keysym.h>

#include "sim.h"

static struct {
    Display *dpy;
    Window win;
    GC gc;
    XImage *img;
    Atom wm_delete;
    int w, h, scale;
    bool headless;
    bool quit;

    int mx, my;
    bool pressed;

    lv_group_t *group;
    lv_indev_t *indev_ptr;
    lv_indev_t *indev_key;

    uint32_t keys[32];
    int key_head, key_tail;
    uint32_t last_key;

    uint16_t *shadow;   /* 整帧影子：Expose 重画 + headless 截图都靠它 */
} s;

uint32_t sim_tick_ms(void)
{
    struct timespec ts;

    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (uint32_t)((uint64_t)ts.tv_sec * 1000u + (uint64_t)ts.tv_nsec / 1000000u);
}

static inline uint32_t rgb565_to_xrgb(uint16_t c)
{
    uint32_t r = (uint32_t)((c >> 11) & 0x1Fu);
    uint32_t g = (uint32_t)((c >> 5) & 0x3Fu);
    uint32_t b = (uint32_t)(c & 0x1Fu);

    r = (r << 3) | (r >> 2);
    g = (g << 2) | (g >> 4);
    b = (b << 3) | (b >> 2);
    return (r << 16) | (g << 8) | b;
}

/* 把影子缓冲的一块画到窗口（只画脏矩形，缩放用最近邻）。 */
static void blit_rect(int x0, int y0, int w, int h)
{
    if (s.headless || !s.dpy || !s.img) {
        return;
    }

    const int sc = s.scale;
    const int iw = s.w * sc;
    const bool fast = (s.img->bits_per_pixel == 32);

    for (int y = 0; y < h; y++) {
        const uint16_t *src = s.shadow + (size_t)(y0 + y) * (size_t)s.w + x0;
        for (int sy = 0; sy < sc; sy++) {
            int row = (y0 + y) * sc + sy;
            for (int x = 0; x < w; x++) {
                uint32_t rgb = rgb565_to_xrgb(src[x]);
                for (int sx = 0; sx < sc; sx++) {
                    int col = (x0 + x) * sc + sx;
                    if (fast) {
                        ((uint32_t *)s.img->data)[(size_t)row * (size_t)iw + col] = rgb;
                    } else {
                        XPutPixel(s.img, col, row, rgb);
                    }
                }
            }
        }
    }
    XPutImage(s.dpy, s.win, s.gc, s.img, x0 * sc, y0 * sc, x0 * sc, y0 * sc,
              (unsigned)w * (unsigned)sc, (unsigned)h * (unsigned)sc);
    XFlush(s.dpy);
}

/* ── LVGL flush ────────────────────────────────────────────────── */

static void flush_cb(lv_display_t *disp, const lv_area_t *area, uint8_t *px_map)
{
    const int w = (int)lv_area_get_width(area);
    const int h = (int)lv_area_get_height(area);
    const uint16_t *px = (const uint16_t *)px_map;

    for (int y = 0; y < h; y++) {
        memcpy(s.shadow + (size_t)(area->y1 + y) * (size_t)s.w + area->x1,
               px + (size_t)y * (size_t)w, (size_t)w * 2u);
    }
    blit_rect(area->x1, area->y1, w, h);
    lv_display_flush_ready(disp);
}

/* ── 输入 ──────────────────────────────────────────────────────── */

