/**
 * @brief 画布专属 arena（板端是固定地址 + MPU write-back）。
 *
 * PC 上没有 MPU，write-back 与否无意义；这里只保证"基址稳定、够大、不参与 free"，
 * 让 vmap_view 走它优先的那条路径（否则会看到 "canvas fallback pool" 警告）。
 */
void *board_psram_canvas_arena(size_t *bytes)
{
#define SIM_CANVAS_ARENA_BYTES (8u * 1024u * 1024u)
    static void *arena;

    if (arena == NULL) {
        if (posix_memalign(&arena, 64, SIM_CANVAS_ARENA_BYTES) != 0) {
            arena = NULL;
            return NULL;
        }
        memset(arena, 0, SIM_CANVAS_ARENA_BYTES);
    }
    if (bytes) {
        *bytes = SIM_CANVAS_ARENA_BYTES;
    }
    return arena;
}

