/* ══════════════════════════════════════════════════════════════════════════
 * UI 命令队列（ctl）：单线程里的真 FIFO，投递什么就能取出什么
 * ══════════════════════════════════════════════════════════════════════════ */

#define SIM_CTL_QUEUE_LEN 8

static struct {
    myvendor_bicycle_ctl_msg_t msg[SIM_CTL_QUEUE_LEN];
    unsigned head;
    unsigned tail;
} s_ctl;

static char s_ctl_state[MYVENDOR_BICYCLE_CTL_STATE_COUNT][64];

int myvendor_bicycle_ctl_post(myvendor_bicycle_ctl_op_t op, const char *arg)
{
    unsigned next = (s_ctl.tail + 1u) % SIM_CTL_QUEUE_LEN;

    if (next == s_ctl.head) {
        return -ENOSPC;
    }
    memset(&s_ctl.msg[s_ctl.tail], 0, sizeof(s_ctl.msg[0]));
    s_ctl.msg[s_ctl.tail].op = (uint8_t)op;
    if (arg) {
        snprintf(s_ctl.msg[s_ctl.tail].arg, sizeof(s_ctl.msg[0].arg), "%s", arg);
    }
    s_ctl.tail = next;
    return 0;
}

bool myvendor_bicycle_ctl_take(myvendor_bicycle_ctl_msg_t *msg)
{
    if (s_ctl.head == s_ctl.tail) {
        return false;
    }
    if (msg) {
        *msg = s_ctl.msg[s_ctl.head];
    }
    s_ctl.head = (s_ctl.head + 1u) % SIM_CTL_QUEUE_LEN;
    return true;
}

void myvendor_bicycle_ctl_state_set(myvendor_bicycle_ctl_state_id_t id, const char *value)
{
    if ((unsigned)id >= MYVENDOR_BICYCLE_CTL_STATE_COUNT) {
        return;
    }
    snprintf(s_ctl_state[id], sizeof(s_ctl_state[id]), "%s", value ? value : "");
}

