bool myvendor_devctl_tz_hms(long utc_sec, int *hour, int *min)
{
    long local = utc_sec + (long)s_pol.tz_min * 60L;
    long sod = local % 86400L;

    if (sod < 0) {
        sod += 86400L;
    }
    if (hour) {
        *hour = (int)(sod / 3600L);
    }
    if (min) {
        *min = (int)((sod % 3600L) / 60L);
    }
    return true;
}

