            "[vblit] probe done ovl_bits=0x%03x (bit=dirx*3+diry; dirx/diry: 0=-,1=0,2=+) fill=%u nonovl=%u total=%u cyc",
            (unsigned)bits, (unsigned)(b->fill_ok ? 1u : 0u),
            (unsigned)(b->nonovl_ok ? 1u : 0u), (unsigned)(vl_cyc() - t0));
    }

    vmap_free(abuf);
    vmap_free(bbuf);
    s_probe_ok = true;
    return true;
}

