void *gpx_port_malloc(size_t size)
{
  return board_malloc_psram(size);
}

void *gpx_port_calloc(size_t nmemb, size_t size)
{
  size_t total;
  void *ptr;

  if (nmemb != 0 && size > (size_t)-1 / nmemb)
    {
      return NULL;
    }

  total = nmemb * size;
  ptr   = board_malloc_psram(total);
  if (ptr != NULL)
    {
      memset(ptr, 0, total);
    }

  return ptr;
}

